}

for (long from = 1_900_000_000; from <= lastId; from += 100_000_000) {
    long to = Math.min(from + 100_000_000 - 1, lastId);
    System.out.println("batch " + from + ".." + to);
}

for (double x = 0; x < 1.0; x += 0.1) {
    passes++;
    last = x;
}

